text:
Data Sources
Hazard ranking among Queens CDTAs requires data sources that can be used to differentiate the relative risks between districts. These data are not available for all hazards:



Queens Map HazardData SourceHeavy RainStormwater Flood MapsCoastal StormCurrent-day Storm Surge FVIExtreme HeatHeat Vulnerability IndexExtreme ColdNone availableHazmat / ChemicalChemically Intensive Small BusinessesHazardous Waste Material StorageMass Casualty Event / Active ShooterNone availableInfectious DiseasePandemic Influenza Vulnerability IndexBlackout & Cyberattack (EMP)None available


In the absence of available information at the Community District level, extreme cold, mass casualty events / active shooter incidents, and blackout & cyberattack cannot be ranked.
In order to identify a suitable ranking methodology for the remaining hazards, a discussion of the disparate data is warranted.


Code
# Fetch data sources

cdta &lt;- read_sf("https://services5.arcgis.com/GfwWNkhOj9bNBqoJ/arcgis/rest/services/NYC_Community_District_Tabulation_Areas_2020/FeatureServer/0/query?where=CDTAType=0&outFields=*&outSR=4326&f=pgeojson") |&gt; 
  mutate(cdtaCode = paste0(
    BoroCode,
    str_sub(CDTA2020, -2)
  ))

stormwater_limited &lt;- read_sf("https://github.com/BetaNYC/q-map/releases/download/data-v4/stormwater_limited_1_77.geojson") |&gt; st_make_valid()

stormwater_moderate &lt;- read_sf("https://github.com/BetaNYC/q-map/releases/download/data-v4/stormwater_moderate_2_13.geojson") |&gt; 
  st_make_valid()

ss_cur_fvi &lt;- soc_read(
  "https://data.cityofnewyork.us/Environment/New-York-City-s-Flood-Vulnerability-Index/mrjc-v9pm.json",
  query = soc_query(
    select = "the_geom, GEOID, ss_cur"
  ),
  include_synthetic_cols = FALSE
)

hvi &lt;- read_sf("https://services1.arcgis.com/8cuieNI8NbqQZQVJ/arcgis/rest/services/HVI_by_CDTA_CRAD_2024/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson")

chem_small_biz &lt;- read_sf("https://services3.arcgis.com/A6Zjpzrub8ESZ3c7/arcgis/rest/services/Chemically%20Intensive%20Small%20Businesses_2/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson")

hazmat_storage &lt;- read_sf("https://services6.arcgis.com/yG5s3afENB5iO9fj/arcgis/rest/services/EPA_RCA_Fuel_Oil_Storage/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson")

pivi &lt;- read_sf("https://services1.arcgis.com/8cuieNI8NbqQZQVJ/arcgis/rest/services/Pandemic_Influenza_Vulnerability_Index/FeatureServer/0/query?where=1=1&outFields=*&outSR=4326&f=pgeojson")

# Aggregate where needed

## Stormwater -&gt; CDTA
stormwater_all &lt;- st_union(
  st_union(stormwater_limited),
  st_union(stormwater_moderate)
) |&gt; 
  st_transform(4326) |&gt; 
  st_make_valid()

stormwater_pct &lt;- cdta |&gt; 
  mutate(cdta_area = st_area(geometry)) |&gt; 
  st_intersection(stormwater_all) |&gt; 
  transmute(CDTA2020,
            stormwater_pct = as.numeric(st_area(geometry) / cdta_area) * 100) |&gt;
  st_drop_geometry()

cdta &lt;- cdta |&gt; 
  left_join(stormwater_pct) |&gt; 
  mutate(stormwater_pct = replace_na(stormwater_pct, 0))

## Tract-level FVI -&gt; CDTA
# Assign max FVI to CD
ss_cur_fvi_cd &lt;- ss_cur_fvi |&gt; 
  st_join(cdta |&gt; select(CDTA2020),
          largest = TRUE)

ss_cur_fvi_cd &lt;- ss_cur_fvi_cd |&gt; 
  st_drop_geometry() |&gt; 
  group_by(CDTA2020) |&gt; 
  summarize(max_ss_cur_fvi = max(ss_cur, na.rm = T))

cdta &lt;- cdta |&gt; 
  left_join(ss_cur_fvi_cd)

# Hazmat storage
cdta$hazmat_count &lt;- lengths(st_intersects(cdta, hazmat_storage))

# Join remainder

## HVI
cdta &lt;- cdta |&gt; 
  left_join(hvi |&gt; 
              st_drop_geometry() |&gt; 
              select(CommDist, HVI),
            by = join_by(cdtaCode == CommDist))

## Chemically Intensive Small Business count
cdta &lt;- cdta |&gt; 
  left_join(chem_small_biz |&gt; 
              st_drop_geometry() |&gt; 
              select(BoroCD, top_3) |&gt; 
              mutate(BoroCD = as.character(BoroCD)) |&gt; 
              rename(chem_count = "top_3"),
            by = join_by(cdtaCode == BoroCD))

## PIVI
cdta &lt;- cdta |&gt; 
  left_join(pivi |&gt; 
              st_drop_geometry() |&gt; 
              select(COMMDIST, PIVI),
            by = join_by(cdtaCode == COMMDIST))

cdta &lt;- cdta |&gt; 
  select(BoroCode,CDTA2020, cdtaCode, CDTAName,
         stormwater_pct, max_ss_cur_fvi, hazmat_count, HVI, chem_count, PIVI) |&gt; 
  relocate(geometry, .after = last_col()) |&gt; 
  mutate(max_ss_cur_fvi = as.integer(max_ss_cur_fvi))
